        }
        .documentheaderleft { display: flex; alignitems: center; gap: 0.5rem; width: 120px; }
        .documentheaderright { 
            display: flex; alignitems: center; gap: 0.5rem; width: 120px; 
            justifycontent: flexend;
        }
        .compactbtn {
            width: 32px; height: 32px;
            background: var(glassstrong); border: 1px solid var(border);
            borderradius: 6px; color: var(text); cursor: pointer;
            display: flex; alignitems: center; justifycontent: center;
            transition: all 0.3s var(transitioncurve);
            fontsize: 0.8rem;
        }
        .compactbtn:hover, .compactbtn:active {
            background: var(glassstrong); bordercolor: var(borderglow);
            transform: translateY(2px);
        }
        .documentcontent { 
            flex: 1; overflowy: auto; padding: 1.5rem; 
            maxwidth: 1000px; margin: 0 auto;
        }
        .documentsection { 
            marginbottom: 2rem; 
        }
        .documentsection h3 {
            color: var(secondary); 
            paddingbottom: 0.5rem; marginbottom: 1rem; 
            fontweight: 600; fontsize: 1rem;
            borderbottom: 1px solid var(border);
            background: lineargradient(135deg, var(primary), var(secondary));
            webkitbackgroundclip: text; webkittextfillcolor: transparent;
        }
        .synthesiscontent { 
