        }
        .synthesiscontent h1, .synthesiscontent h2, .synthesiscontent h3 {
            background: lineargradient(135deg, var(primary), var(secondary));
            webkitbackgroundclip: text; webkittextfillcolor: transparent;
            fontweight: 600; margintop: 1.5rem; marginbottom: 0.8rem;
        }
