        .sourcedate { 
            display: block; color: var(textmuted); fontsize: 0.7rem; 
            margintop: 0.5rem; fontweight: 400;
        }

        / iOSszerű animációk és interakciók /
        .iosbounce {
            animation: iosBounce 0.3s easeout;
        }

        @keyframes iosBounce {
            0% { transform: scale(1); }
            50% { transform: scale(0.95); }
            100% { transform: scale(1); }
        }

        / Érintési visszajelzés /
        .touchfeedback {
            position: relative;
            overflow: hidden;
        }

        .touchfeedback::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            background: rgba(255, 255, 255, 0.3);
            borderradius: 50%;
            transform: translate(50%, 50%);
            transition: width 0.3s ease, height 0.3s ease;
            pointerevents: none;
        }

        .touchfeedback.active::before {
            width: 200px;
            height: 200px;
        }

        / Swipe indikátor /
        .swipeindicator {
            position: fixed;
            top: 50%;
            left: 10px;
            transform: translateY(50%);
            width: 4px;
            height: 60px;
            background: var(accent);
            borderradius: 2px;
            opacity: 0;
            transition: opacity 0.3s ease;
            zindex: 1000;
        }

        .swipeindicator.show {
            opacity: 0.7;
        }

        / Pulltorefresh indikátor /
        .pullrefresh {
            position: fixed;
            top: 60px;
            left: 50%;
            transform: translateX(50%);
            width: 40px;
            height: 40px;
            background: var(glass);
            borderradius: 50%;
            display: flex;
            alignitems: center;
            justifycontent: center;
            transition: top 0.3s ease;
            zindex: 1000;
        }

        .pullrefresh.active {
            top: 20px;
        }

        .pullrefresh svg {
            width: 20px;
            height: 20px;
            color: var(accent);
            animation: spin 1s linear infinite;
        }

        @keyframes spin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }

        / Gomb pressed állapot /
        .btnpressed {
            transform: scale(0.95) !important;
            opacity: 0.8 !important;
        }

        / Mobil nézet optimalizációk /
        @media (maxwidth: 768px) {
            .sidebar { width: 240px; }
            .headertitle { fontsize: 0.9rem; }
            .messagescontainer, .inputarea { padding: 12px; }
