            .sourceitem { padding: 0.8rem; gap: 0.8rem; }
            .welcometitle { fontsize: 2rem; }
            .welcomesubtitle { fontsize: 0.9rem; }
        }

        / Nagyon kicsi mobil eszközökre /
        @media (maxwidth: 480px) {
            .sidebar { width: 220px; }
            .header { padding: 6px 12px; height: 48px; }
