            transition: width 0.5s ease;
            min-width: 2px;
        }
        .progress-text {
            display: flex; justify-content: space-between;
            font-size: 0.75rem; color: var(--text-muted);
        }
        .phase-indicator {
            font-size: 0.8rem; color: var(--text);
